package br.com.onda;
import java.net.*;
import java.util.*;
/** One explicit provider per URL; no third-party download servers. */
final class MediaDownloads {
 static YoutubeDownloads.Result inspect(String input)throws Exception{String url=MediaLinks.resolve(input);if(MediaLinks.isTikTok(url)){PublicMediaHttp.Page page=PublicMediaHttp.read(url,true);String id=MediaLinks.videoId(page.url);if(id.isEmpty())throw new Exception("O link curto não levou a um vídeo público do TikTok. Pode estar expirado ou exigir verificação.");TiktokPage.Clip clip=TiktokPage.parse(page.text(),id);return tiktok(available(clip,page.url),page.url);}
  if(MediaLinks.isYoutube(url))return YoutubeDownloads.inspect(url);
  String extension=MediaLinks.extension(url);if(extension.isEmpty())return fromPublicPage(PublicMediaHttp.readPage(url),PublicMediaHttp::readMediaPrefix);
  PublicMediaHttp.Page page=PublicMediaHttp.read(url,false);if(!PublicMediaHttp.mediaHeader(page.bytes,extension))throw new Exception("O endereço não retornou um arquivo "+extension.toUpperCase(Locale.ROOT)+" reconhecível.");String name=new URI(url).getPath();name=name.substring(name.lastIndexOf('/')+1);return new YoutubeDownloads.Result(name,fileOptions(page,extension,"",""));
 }
 static List<YoutubeDownloads.Option> fileOptions(PublicMediaHttp.Page page,String extension,String referer,String label){List<YoutubeDownloads.Option> out=new ArrayList<>();out.add(new YoutubeDownloads.Option(label+extension.toUpperCase(Locale.ROOT)+" • arquivo original",page.url,null,extension,mime(extension),true,referer));if(!extension.equals("mp3")){out.add(new YoutubeDownloads.Option(label+"MP3 • extrair áudio AAC e converter • 192 kbps",page.url,null,"mp3","audio/mpeg",false,referer));if(!extension.equals("m4a"))out.add(new YoutubeDownloads.Option(label+"M4A • extrair áudio AAC",page.url,null,"m4a","audio/mp4",false,referer));if(!extension.equals("aac"))out.add(new YoutubeDownloads.Option(label+"AAC • extrair sem recodificar",page.url,null,"aac","audio/aac",false,referer));}return out;}
 static YoutubeDownloads.Result fromPublicPage(PublicMediaHttp.Page page,PrefixReader reader)throws Exception{
  PublicMediaPage parsed=PublicMediaPage.parse(page.text(),page.url);List<YoutubeDownloads.Option> options=new ArrayList<>();long deadline=System.currentTimeMillis()+45000;int checked=0,found=0;
  for(PublicMediaPage.Candidate candidate:parsed.media){if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Análise cancelada");if(checked++>=6||found>=3||System.currentTimeMillis()>deadline)break;try{PublicMediaHttp.Page file=reader.read(candidate.url,page.url);String type=PublicMediaPage.fromMime(file.type);String extension=type.isEmpty()?candidate.extension:type;if(!PublicMediaHttp.mediaHeader(file.bytes,extension))continue;found++;options.addAll(fileOptions(file,extension,page.url,"Fonte "+found+" • "));}catch(java.io.InterruptedIOException error){if(Thread.currentThread().isInterrupted())throw error;}catch(Exception ignored){}}
  if(options.isEmpty())throw new java.io.IOException("A página não disponibilizou um arquivo MP4, MP3, M4A ou AAC acessível. Players carregados por scripts, login, DRM e listas HLS/DASH não são suportados por esta análise. Tente o link direto do arquivo.");return new YoutubeDownloads.Result(parsed.title,options);
 }

 interface PrefixReader {PublicMediaHttp.Page read(String url,String referer)throws Exception;}
 static TiktokPage.Clip available(TiktokPage.Clip clip,String page)throws Exception{return available(clip,page,PublicMediaHttp::readMediaPrefix);}
 static TiktokPage.Clip available(TiktokPage.Clip clip,String page,PrefixReader reader)throws Exception{String referer=MediaLinks.tiktok(page);String last="";for(String candidate:clip.candidates){if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Consulta cancelada");try{PublicMediaHttp.Page prefix=reader.read(candidate,referer);if(PublicMediaHttp.mediaHeader(prefix.bytes,"mp4"))return new TiktokPage.Clip(clip.title,prefix.url);last="O endereço retornou uma página em vez do vídeo.";}catch(java.io.InterruptedIOException interrupted){if(Thread.currentThread().isInterrupted())throw interrupted;last="Tempo limite ao conferir o arquivo.";}catch(Exception error){last=error.getMessage();}}throw new Exception("O TikTok informou o vídeo, mas não liberou nenhum dos arquivos públicos consultados. "+last);}
 static YoutubeDownloads.Result tiktok(TiktokPage.Clip clip,String page)throws Exception{String id=MediaLinks.videoId(page);if(id.isEmpty())throw new Exception("Vídeo inválido");String referer=MediaLinks.tiktok(page);List<YoutubeDownloads.Option> options=new ArrayList<>();options.add(new YoutubeDownloads.Option("TikTok • MP4 original",clip.video,null,"mp4","video/mp4",true,referer));options.add(new YoutubeDownloads.Option("MP3 • áudio do vídeo • 192 kbps",clip.video,null,"mp3","audio/mpeg",false,referer));options.add(new YoutubeDownloads.Option("M4A • extrair áudio AAC do vídeo",clip.video,null,"m4a","audio/mp4",false,referer));return new YoutubeDownloads.Result(clip.title,options);}
 static String mime(String extension){return extension.equals("mp3")?"audio/mpeg":extension.equals("aac")?"audio/aac":extension.equals("m4a")?"audio/mp4":"video/mp4";}
}
